/**
 *
 * Popover component is used to display a popover to the user.
 *
 * [Live Demo](https://www.primereact.org/popover/)
 *
 * @module PopoverRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UsePopoverExposes, UsePopoverOpenChangeEvent, UsePopoverProps, UsePopoverState } from '@primereact/types/headless/popover';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Defines passthrough(pt) options type in Popover component.
 */
export type PopoverRootPassThroughType<E> = PassThroughType<PopoverRootInstance, E>;
/**
 * Defines passthrough(pt) options of Popover component.
 */
export interface PopoverRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the trigger's DOM element.
     */
    trigger?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the positioner's DOM element.
     */
    positioner?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the popup's DOM element.
     */
    popup?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the arrow's DOM element.
     */
    arrow?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the header's DOM element.
     */
    header?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the title's DOM element.
     */
    title?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the description's DOM element.
     */
    description?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the content's DOM element.
     */
    content?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the footer's DOM element.
     */
    footer?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the close's DOM element.
     */
    close?: PopoverRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in Popover component.
 */
export interface PopoverRootProps extends BaseComponentProps<PopoverRootInstance, UsePopoverProps, PopoverRootPassThrough> {
}
/**
 * Defines valid state in Popover component.
 * @extends UsePopoverState
 */
export interface PopoverRootState extends UsePopoverState {
}
/**
 * Defines the methods and properties exposed by Popover component.
 * @extends UsePopoverExposes
 */
export interface PopoverRootExposes extends UsePopoverExposes {
}
/**
 * Event fired when the popover's open state changes.
 * @extends UsePopoverOpenChangeEvent
 */
export interface PopoverRootOpenChangeEvent extends UsePopoverOpenChangeEvent {
}
/**
 * Instance of Popover component.
 */
export type PopoverRootInstance = ComponentInstance<PopoverRootProps, PopoverRootState, PopoverRootExposes>;
